    @staticmethod
    def _parse_credential_restriction(credential) -> "CredentialRestriction":
        """Convert a Microsoft Graph credential restriction into a model instance."""
        restriction_type = getattr(credential, "restriction_type", None)
        if hasattr(restriction_type, "value"):
            restriction_type = restriction_type.value

        state = getattr(credential, "state", None)
        if hasattr(state, "value"):
            state = state.value

        max_lifetime = getattr(credential, "max_lifetime", None)

        return CredentialRestriction(
            restriction_type=(
                str(restriction_type) if restriction_type is not None else ""
            ),
            state=str(state) if state is not None else "",
            max_lifetime=(str(max_lifetime) if max_lifetime is not None else None),
        )

    async def _get_default_app_management_policy(
        self,
    ) -> Optional["DefaultAppManagementPolicy"]:
        """Retrieve the tenant default application management policy.

        Fetches the default app management policy from Microsoft Graph, including
        the credential restrictions applied to password and key credentials.

        Returns:
            A DefaultAppManagementPolicy object, or None if retrieval fails.
        """
        logger.info("Entra - Getting default app management policy...")
        default_app_management_policy = None
        try:
            policy = await self.client.policies.default_app_management_policy.get()

            application_restrictions = None
            app_restrictions = getattr(policy, "application_restrictions", None)
            if app_restrictions is not None:
                password_credentials = [
                    self._parse_credential_restriction(credential)
                    for credential in (
                        getattr(app_restrictions, "password_credentials", []) or []
                    )
                ]
                key_credentials = [
                    self._parse_credential_restriction(credential)
                    for credential in (
                        getattr(app_restrictions, "key_credentials", []) or []
                    )
                ]
                application_restrictions = AppManagementRestrictions(
                    password_credentials=password_credentials,
                    key_credentials=key_credentials,
                )

            default_app_management_policy = DefaultAppManagementPolicy(
                id=getattr(policy, "id", "") or "",
                name=getattr(policy, "display_name", "") or "",
                description=getattr(policy, "description", None),
                is_enabled=bool(getattr(policy, "is_enabled", False)),
                application_restrictions=application_restrictions,
            )
        except Exception as error:
            logger.error(
                f"{error.__class__.__name__}[{error.__traceback__.tb_lineno}]: {error}"
            )
        return default_app_management_policy


